# ╔═╡ 36a6e43f-6bcf-4c27-bfbb-047760e77ada
md"""
# Chapter 13 Policy Gradient Methods Introduction
Instead of selection actions based on *action-value estimates* we learn a *parameterized policy* with parameters θ.  $\pi(a|s, \mathbf{\theta}) = \text{Pr}\{A_t=a|S_t=s, \mathbf{\theta}_t=\mathbf{\theta\}}$ denotes the probability that action *a* is taken at time *t* given that the environment is in state *s* at time *t* with parameter **θ**.  

We consider methods that improve the policy parameter using the gradient of some scalar performance measure $J(\mathbf{\theta})$ with respect to the policy parameters.  We follow gradient ascent since we are trying to maximize this value and methods that use this approach are called *policy gradient methods*.  Methods that learn approximations to both policy and value functions are often called *actor-critic methods*, where 'actor' is a reference to the learned policy, and 'critic' refers to the learned value function, usually a state-value function.
## 13.1 Policy Approximation and its Advantages
"""

# ╔═╡ 31f7e903-30b6-4193-9174-88093e004de4
md"""
In policy gradient methods, the policy can be parameterized in any way, as long as $\pi(a \vert s, \mathbf{\theta})$ is differentiable with respect to its parameters, that is, as long as $\nabla \pi(a \vert s, \mathbf{\theta})$ exists and is finite for all $s \in \mathcal{S}, a \in \mathcal{A}(s)$, and $\mathbf{\theta} \in \mathbb{R}^{d^\prime}$ where $d^\prime$ is the number of parameters.

If the action space is discrete and not too large then we can have numerical preferences for each state/action pair parameterized by $\mathbf{\theta}$.  $h(s, a, \mathbf{\theta})$ and the corresponding policy can be to select actions according to the probability distribution generated by the soft-max.  $\pi(a|s, \mathbf{\theta}) \doteq \frac{\exp{h(s, a, \mathbf{\theta})}}{\sum_b \exp{h(s, b, \mathbf{\theta})}}$.  One advantage of using the soft-max is that the optimal policy can be stochastic or we can approach a deterministic policy by selecting the action with the highest probability.  If we include a temperature parameter in the soft-max then we can vary the same policy to be more or less stochastic as needed.

If we calculate preferences with linear features, then we would have feature vectors $\mathbf{x}(s, a) \in \mathbb{R}^{d^\prime}$ to match with the parameter vector $\mathbf{\theta} \in \mathbb{R}^{d^\prime}$.  Then the preferences would be calculated:

$h(s, a, \mathbf{\theta}) = \mathbf{\theta}^\top \mathbf{x}(s, a)$

Another advantage is that for some problems the policy may be easier to approximate than the action-value function.  We can also inject some prior knowledge of the environment into how the policy is parametrized.
"""

# ╔═╡ 48dcd2d0-a940-41da-a097-90c780f2ec4d
md"""
### Alternative Paramaterization

If the action space is small enough, then it may be convenient to create a function that simply outputs the preferences for all of the actions at a given state.  Let's call $N_a$ to be the number of available actions.  We would then consider the vector function $\mathbf{h}(s, \mathbf{\theta}) \in \mathbb{R}^{N_a}$ and its components $h_1, h_2, h_3, \dots, h_{N_a}$. To be the action preferences at each state.  With this style of paramaterization, we need only compute state feature vectors $\mathbf{x}(s) \in \mathbb{R}^d$.

Similarly, the policy function would also be a vector function.  In order to compute the softmax, we must evaluate the denominator of (13.2) which requires knowing all of the action preferences.  Practically, it is only defined as a function on vectors, so consider the following notation to simplify expressions where we use the symbol $\mathbf{\sigma}$ to denote the soft-max vector function.  

$\sigma(\mathbf{x}) = \frac{e^{\mathbf{x}}}{\sum_j{e^{x_j}}} \text{ where we abuse the notation } e^{\mathbf{x}} = \begin{pmatrix}
e^{x_1} \\
e^{x_2} \\
\vdots \\
e^{x_n}
\end{pmatrix}$

Using this notation, we can write down the policy function under this new parameterization: $\mathbf{\pi}(s, \mathbf{\theta}) = \mathbf{\sigma}(\mathbf{h}(s, \mathbf{\theta}))$.  What do linear preferences look like with this parameterization?  Instead of a parameter vector $\mathbf{\theta} \in \mathbb{R}^{d^\prime}$, we have a parameter matrix $\mathbf{\theta} \in \mathbb{R}^{d \times N_a}$ and the vector of preferences is the result of a matrix vector multiplication: $\mathbf{h}(s, \mathbf{\theta}) = \theta^\top \mathbf{x}(s) \in \mathbb{R}^{N_a}$.  Subscript notation is used to refer to single preference values so $\mathbf{h}_i$ would be the $ith$ index of $\mathbf{h}$ for the $ith$ action preference equivalent to $h_i$.
"""

# ╔═╡ d95f75b5-21d8-4862-baa7-50b58d9725b8
md"""
### Soft-max notation and gradients

To use policy gradient methods, we must be able to take the gradient of the policy function for every state-action pair.  Using the above notation and treating the policy as a vector function, we must know the gradient of the soft-max applied to a vector function at a particular index.  Each gradient is a column vector of length $d$ where $d$ is the number of parameters.  There is a separate gradient available for every index in the vector output which is one for each action or a total of $N_a$.  To simplify expressions, $\mathbf{h}(s, \mathbf{\theta})$ will we written as $\mathbf{h}$ and $\mathbf{\pi} = \mathbf{\sigma}(\mathbf{h})$.  Our desired gradient is with respect to a particular component of $\mathbf{\sigma}(\mathbf{h})$ denoted $\mathbf{\sigma}(\mathbf{h})_a$ where $a$ represents the action index.  The gradient itself is the vector of partial derivatives with respect to the parameters $\theta$.  The $ith$ component of the gradient $\nabla(f(\theta))_i = \frac{\partial f(\theta)}{\partial \theta_i}$.  When we compute the gradient we need all the components whose expression is derived below.   

$\begin{align}
\nabla \left ( \sigma(\mathbf{h})_a \right )_i &= \frac{\partial}{\partial \theta_i} \left ( \frac{e^{h_a}}{\sum_k{e^{h_k}}} \right ) \\
&=\left ( \frac{1}{{\sum_k{e^{h_k}}}} \right )^2 \left ( e^{h_a} \frac{\partial{h_a}}{\partial{\theta_i}}  \sum_k{e^{h_k}}  - e^{h_a} \sum_k{e^{h_k} \frac{\partial{h_k}}{\partial{\theta_i}}} \right )  \\
&=\left ( \frac{1}{{\sum_k{e^{h_k}}}} \right )^2 e^{h_a} \left ( \frac{\partial{h_a}}{\partial{\theta_i}}  \sum_k{e^{h_k}}  - \sum_k{e^{h_k} \frac{\partial{h_k}}{\partial{\theta_i}}} \right )  \tag{factoring out exponenential term}\\
&=\left ( \frac{e^{h_a}}{{\sum_k{e^{h_k}}}} \right ) \left ( \frac{\partial{h_a}}{\partial{\theta_i}}  \sum_k{\frac{e^{h_k}}{\sum_l e^{h_l}}}  - \sum_k{\frac{e^{h_k}}{\sum_l e^{h_l}} \frac{\partial{h_k}}{\partial{\theta_i}}} \right )  \tag{distributing squared fraction}\\
&=\pi_a \left ( \frac{\partial{h_a}}{\partial{\theta_i}}  \sum_k{\pi_k}  - \sum_k{\pi_k \frac{\partial{h_k}}{\partial{\theta_i}}} \right )  \tag{definition of policy function}\\
&=\pi_a \left ( \frac{\partial{h_a}}{\partial{\theta_i}}  - \sum_k{\pi_k \frac{\partial{h_k}}{\partial{\theta_i}}} \right )
\end{align}$ 

The final step results form the fact that the policy function is a probability distribution so the sum over it is always 1.
"""

# ╔═╡ fc3dcd26-c5cf-4141-bf6c-eaed5fc9bb1d
md"""
Consider the linear parameterization proposed with $h_a = \mathbf{\theta}^\top \mathbf{x}(s, a)$:  

$\frac{\partial{h_a}}{\partial{\theta_i}} = \mathbf{x}(s, a)_i \implies \nabla(\pi(a \vert s, \mathbf{\theta}))_i = \pi_a \left ( \mathbf{x}(s, a)_i - \sum_k \pi_k \mathbf{x}(s, k)_i \right)$ 

Now consider $\mathbf{h} = \theta ^ \top \mathbf{x}$ with $h_a = \mathbf{h}_a$.  Since the parameters are now represented as a matrix, we can also index the gradient partial derivatives such that $\nabla \left ( f(\theta) \right )_{i, j} = \frac{\partial f(\theta)}{\theta_{i, j}}$

$\frac{\partial{h_a}}{\partial{\theta_{i, j}}} = \begin{cases} 
\mathbf{x}(s)_i, & \text{ if } j = a \\
0, & \text{ else }
\end{cases}
\implies \nabla(\pi(s, \mathbf{\theta})_a)_{i, j} = \pi_a \left ( \frac{\partial h_a}{\partial \theta_{i, j}} - \sum_k \pi_k \frac{\partial h_k}{\partial \theta_{i, j}} \right)=\pi_a \begin{cases}
\mathbf{x}(s)_i (1 - \pi_j), & \text{ if } j = a \\
-\pi_j \mathbf{x}(s)_i, & \text{ else }\\
\end{cases}$ 
"""

# ╔═╡ dcb306ae-a1b1-43d6-ba6e-e38668838689
md"""
### *Soft-max Implementation*
"""

# ╔═╡ 33c99850-67cd-4754-94b9-6df97b238e27
function soft_max!(x::AbstractVector{T}) where T<:Real
	minx, maxx = extrema(x)
	if minx == maxx
		x .= one(T) / length(x)
		return x
	end
	s = zero(T)
	@inbounds @simd for i in eachindex(x)
		h = exp(x[i] - maxx)
		s += h
		x[i] = h
	end
	x ./= s
end

# ╔═╡ 7a6fb1f0-fc3c-4c29-a6d9-769d32ca98a9
md"""
### Example 13.1 Short corridor gridworld
"""

# ╔═╡ 5cc4d12d-b537-47e2-8109-4e7a234fdf25
function make_corridor_mdp()
	function step(s::Integer, i_a::Integer)
		δ = 2*i_a - 3 #calculates the s change -1 for left (1) and 1 for right (2)
		switch = iseven(s) #returns true in state 2 which is where actions are switched, when switch is true, multiply δ by -1, otherwise by 1
		c = 1 - 2*switch
		s′ = max(1, s + c*δ)
		(-1f0, s′)
	end

	actions = [:left, :right]

	ptf = StateMDPTransitionSampler(step, 1)
	StateMDP(actions, ptf, () -> 1, s -> s == 4)
end

# ╔═╡ ff76ef94-fdf5-41f3-a31a-21c4629efabe
# ╠═╡ skip_as_script = true
#=╠═╡
const corridor_mdp = make_corridor_mdp()
  ╠═╡ =#

# ╔═╡ f7433324-acc3-49a5-b5b3-ada0c8f09d52
#=╠═╡
runepisode(corridor_mdp)
  ╠═╡ =#

# ╔═╡ fb8904a9-ae64-41cc-93b6-5a25855edad0
#=╠═╡
function get_corridor_episode_stats(p::Real; ntrials=10_000)
	1:ntrials |> Map(_ -> runepisode(corridor_mdp; π = s -> (rand() < p) + 1) |> first |> length) |> foldxt(+) |> a -> a / ntrials
end
  ╠═╡ =#

