function get_corridor_episode_stats(π::Function; ntrials=10_000, kwargs...)
	1:ntrials |> Map(_ -> runepisode(corridor_mdp; π = π, kwargs...) |> first |> length) |> foldxt(+) |> a -> a / ntrials
end
