# ╠═╡ disabled = true
#=╠═╡
# this is for continuing value iteration from some existing value function
begin_value_iteration_v(mdp::NamedTuple, γ::Real, V; θ = eps(0.0), nmax=Inf, kwargs...) = begin_value_iteration_v(θ, γ, mdp, V, nmax; kwargs...)
