# ╔═╡ 5ac09667-ad41-4b8e-ab7a-857643a69511
#identify states where two policies differ 
function compare_actions(π1, π2, states)
	compactions = [s => (π1[s], π2[s]) for s in states]
	Dict(filter(a -> a[2][1] != a[2][2], compactions))
end

